use canvas_core::{error_archive::ErrorArchive as A,remote_error::RemoteErrorLeaf,payload_codec::Value as V,binary_plist_writer};use std::{collections::BTreeMap,path::Path};
fn leaf(name:&str,crash:bool,native:bool)->A{A::Leaf(RemoteErrorLeaf::from_dictionary(&BTreeMap::from([("errorType".into(),V::String("leaf".into())),("errorTypeDescription".into(),V::String(name.into())),("isPotentialCrash".into(),V::Boolean(crash)),("isNative".into(),V::Boolean(native))])).unwrap())}
fn wrap(main:A,underlying:A)->A{A::Wrapper{main:Box::new(main),underlying:Box::new(underlying)}}
fn main(){let arg=std::env::args().nth(1).unwrap();let dir=Path::new(&arg);std::fs::create_dir_all(dir).unwrap();for name in ["simple","nested-main","nested-underlying"]{let main=leaf("main",true,false);let cause=leaf("cause 🪨",false,true);let root=leaf("root",true,true);let value=match name{"simple"=>wrap(main,cause),"nested-main"=>wrap(wrap(main,cause),root),_=>wrap(main,wrap(cause,root))};std::fs::write(dir.join(format!("{name}.bplist")),binary_plist_writer::encode_dictionary(&value.to_dictionary().unwrap()).unwrap()).unwrap();}}
